import {EXPANSION_PACKS} from './race-packs.js';
export const raceArt=(race)=>EXPANSION_PACKS.find(p=>p.id===race)?.art??null;
const relative=file=>file?.startsWith('../')?file:'../'+file;
function sprite(row){return {...structuredClone(row),frames:row.frames.map(f=>({...f,file:relative(f.file),solidBBox:f.solidBBox??f.alphaBBox})),animations:Object.fromEntries(Object.entries(row.animations??{}).map(([kind,ids])=>[kind,ids.map(id=>typeof id==='number'?row.frames[id]?.id:id)]))};}
export function extendBattleManifest(base){const m=structuredClone(base);m.sprites??={};m.backgrounds??=[];m.monsterSprites??={};m.areaBackgrounds??={};m.areaBaselines??={};m.raceHeroSprites??={};m.raceHeroNeutralSprites??={};m.raceHeroWeaponSprites??={};for(const p of EXPANSION_PACKS){const a=p.art;if(!a)continue;const variants=a.heroWeapons??(a.hero?.frames?{}:a.hero??{});m.raceHeroWeaponSprites[p.id]??={};for(const [weapon,row]of Object.entries(variants)){if(!row?.frames)continue;const key='hero-'+p.id+'-'+weapon;m.sprites[key]=sprite(row);m.raceHeroWeaponSprites[p.id][weapon]=key;}if(a.hero?.frames){const key='hero-'+p.id;m.sprites[key]=sprite(a.hero);}delete m.raceHeroSprites[p.id];delete m.raceHeroNeutralSprites[p.id];if(a.heroNeutral?.frames){const key=p.id+'-hero-neutral';m.sprites[key]=sprite(a.heroNeutral);m.raceHeroNeutralSprites[p.id]=key;m.raceHeroSprites[p.id]=key;}for(const [id,row]of Object.entries(a.monsters??{})){const key='race-'+id;m.sprites[key]=sprite(row);m.monsterSprites[id]=key;}for(const [id,row]of Object.entries(a.areas??{})){const key='race-bg-'+id;if(!m.backgrounds.some(x=>x.id===key))m.backgrounds.push({id:key,file:relative(row.file??row.background),size:row.logicalSize??row.logicalScene??[480,270],z:0});m.areaBackgrounds[id]=[key];m.areaBaselines[id]=row.baselineY??203;}}return m;}
export function raceIconAsset(kind,id,size=32){for(const p of EXPANSION_PACKS){const rows=p.art?.[kind],row=rows&&typeof id==='string'&&Object.hasOwn(rows,id)?rows[id]:null;if(row)return typeof row==='string'?row:row[size]??row.file??null;}return null;}
